import sys

def main():
    raw = sys.stdin.buffer.read()
    data = raw.split()
    if not data:
        return
    neg = {}
    pos = {}
    for x in data:
        if x[0] == 45:
            l = len(x)
            if l in neg:
                neg[l].append(x)
            else:
                neg[l] = [x]
        else:
            l = len(x)
            if l in pos:
                pos[l].append(x)
            else:
                pos[l] = [x]
    out = []
    for l in sorted(neg.keys(), reverse=True):
        b = neg[l]
        b.sort(reverse=True)
        out.extend(b)
    for l in sorted(pos.keys()):
        b = pos[l]
        b.sort()
        out.extend(b)
