import sys

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    # Preallocated buckets for lengths up to 32, fallback dict for larger
    neg = [[] for _ in range(32)]
    pos = [[] for _ in range(32)]
    neg_big = {}
    pos_big = {}
    for x in data:
        l = len(x)
        if x[0] == 45:
            if l < 32:
                neg[l].append(x)
            else:
                neg_big.setdefault(l, []).append(x)
        else:
            if l < 32:
                pos[l].append(x)
            else:
                pos_big.setdefault(l, []).append(x)
    out = []
    for l in sorted(neg_big, reverse=True):
        b = neg_big[l]
        b.sort(reverse=True)
        out.extend(b)
    for l in range(31, 0, -1):
        b = neg[l]
        if b:
            b.sort(reverse=True)
            out.extend(b)
    for l in range(1, 32):
        b = pos[l]
        if b:
            b.sort()
            out.extend(b)
    for l in sorted(pos_big):
        b = pos_big[l]
        b.sort()
        out.extend(b)
    sys.stdout.buffer.write(b'\n'.join(out) + b'\n')

if __name__ == '__main__':
    main()

